INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Hiện tại đơn (Present Simple)','<p data-n11="summary">Diễn tả thói quen, sự thật và lịch trình. Nắm cách chia động từ và nhận biết chủ ngữ số ít.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Dùng hiện tại đơn cho hành động thường xuyên, sự thật, trạng thái ổn định và lịch trình cố định. Với động từ thường, chủ ngữ he/she/it hoặc danh từ số ít đi với V-s/es.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Khẳng định</td><td>S + V(s/es).</td></tr><tr><td>Phủ định</td><td>S + do/does not + V nguyên mẫu.</td></tr><tr><td>Nghi vấn</td><td>Do/Does + S + V nguyên mẫu?</td></tr><tr><td>Động từ be</td><td>I am; he/she/it is; you/we/they are.</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Often, usually, always, sometimes, every day/week. Thêm -es cho động từ kết thúc bằng s, sh, ch, x, o; đổi phụ âm + y thành -ies.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Sau does hoặc does not, động từ chính trở về nguyên mẫu: She does not work, không dùng does not works.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="1" data-order="1"><p class="sentence">Our office opens at eight every weekday.</p><p class="translation">Văn phòng chúng tôi mở cửa lúc tám giờ mỗi ngày trong tuần.</p><p class="note">Our office là số ít; opens diễn tả lịch trình.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The engineers do not work on Sundays.</p><p class="translation">Các kỹ sư không làm việc vào Chủ nhật.</p><p class="note">Chủ ngữ số nhiều dùng do not + work.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Does your manager approve travel requests?</p><p class="translation">Quản lý của bạn có duyệt các đề nghị công tác không?</p><p class="note">Does đứng trước chủ ngữ; approve giữ nguyên mẫu.</p></article></section>','BASIC',1,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Hiện tại đơn (Present Simple)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Hiện tại tiếp diễn (Present Continuous)','<p data-n11="summary">Mô tả việc đang diễn ra và tình huống tạm thời với cấu trúc be + V-ing.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Dùng cho hành động đang diễn ra lúc nói, hoạt động tạm thời trong giai đoạn hiện tại hoặc kế hoạch tương lai đã sắp xếp. Phân biệt với hiện tại đơn mô tả thói quen.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Khẳng định</td><td>S + am/is/are + V-ing.</td></tr><tr><td>Phủ định</td><td>S + am/is/are not + V-ing.</td></tr><tr><td>Nghi vấn</td><td>Am/Is/Are + S + V-ing?</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Now, right now, at the moment, currently. Bỏ e câm trước -ing (write → writing); một số động từ ngắn gấp đôi phụ âm cuối (run → running).</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Động từ chỉ trạng thái như know, own thường không dùng dạng tiếp diễn trong nghĩa thông thường. Chọn is/are dựa trên chủ ngữ.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="4" data-order="1"><p class="sentence">The technician is installing new software now.</p><p class="translation">Kỹ thuật viên đang cài phần mềm mới.</p><p class="note">Is + installing diễn tả việc đang diễn ra.</p></article><article data-example-id="5" data-order="2"><p class="sentence">We are working from home this week.</p><p class="translation">Chúng tôi đang làm việc tại nhà tuần này.</p><p class="note">This week là tình huống tạm thời.</p></article><article data-example-id="6" data-order="3"><p class="sentence">They are meeting the supplier tomorrow.</p><p class="translation">Họ sẽ gặp nhà cung cấp vào ngày mai.</p><p class="note">Tiếp diễn diễn tả cuộc hẹn đã sắp xếp.</p></article></section>','BASIC',2,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Hiện tại tiếp diễn (Present Continuous)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Quá khứ đơn (Past Simple)','<p data-n11="summary">Kể về công việc đã kết thúc trong quá khứ; phân biệt V2/ed và did + V.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Dùng cho hành động đã kết thúc tại một thời điểm trong quá khứ hoặc chuỗi sự kiện nối tiếp. Động từ có quy tắc thêm -ed; động từ bất quy tắc cần học dạng V2.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Khẳng định</td><td>S + V2/ed.</td></tr><tr><td>Phủ định</td><td>S + did not + V nguyên mẫu.</td></tr><tr><td>Nghi vấn</td><td>Did + S + V nguyên mẫu?</td></tr><tr><td>Động từ be</td><td>I/he/she/it was; you/we/they were.</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Yesterday, last week/month/year, two days ago, in 2020. Những mốc quá khứ đã kết thúc thường đi với quá khứ đơn.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Sau did hoặc did not không chia quá khứ động từ chính. Với be, dùng was/were mà không dùng did.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="7" data-order="1"><p class="sentence">The team finished the audit yesterday.</p><p class="translation">Nhóm đã hoàn tất kiểm toán hôm qua.</p><p class="note">Yesterday là mốc quá khứ xác định.</p></article><article data-example-id="8" data-order="2"><p class="sentence">We did not receive the parcel last week.</p><p class="translation">Chúng tôi không nhận được bưu kiện tuần trước.</p><p class="note">Did not + receive nguyên mẫu.</p></article><article data-example-id="9" data-order="3"><p class="sentence">The conference was successful.</p><p class="translation">Hội nghị đã thành công.</p><p class="note">Conference số ít đi với was.</p></article></section>','BASIC',3,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Quá khứ đơn (Past Simple)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Hiện tại hoàn thành (Present Perfect)','<p data-n11="summary">Kết nối quá khứ với hiện tại qua trải nghiệm, kết quả và thời gian kéo dài.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Dùng để nói về trải nghiệm không nêu thời gian quá khứ cụ thể, hành động có kết quả ở hiện tại hoặc việc bắt đầu trước đây và còn tiếp tục. Cấu trúc have/has + V3/ed.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Khẳng định</td><td>S + have/has + V3/ed.</td></tr><tr><td>Phủ định</td><td>S + have/has not + V3/ed.</td></tr><tr><td>Nghi vấn</td><td>Have/Has + S + V3/ed?</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Already, just, yet, ever, never, so far, since + mốc thời gian, for + khoảng thời gian. Không dùng với yesterday/last year khi chúng chỉ thời điểm đã kết thúc.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Phân biệt since 2022 và for three years. Has dùng với chủ ngữ ngôi thứ ba số ít; have dùng với I/you/we/they.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="10" data-order="1"><p class="sentence">We have already sent the quotation.</p><p class="translation">Chúng tôi đã gửi báo giá rồi.</p><p class="note">Already nhấn mạnh kết quả đã hoàn thành.</p></article><article data-example-id="11" data-order="2"><p class="sentence">She has worked here since 2022.</p><p class="translation">Cô ấy làm việc ở đây từ năm 2022 đến nay.</p><p class="note">Since đi với mốc bắt đầu.</p></article><article data-example-id="12" data-order="3"><p class="sentence">Have you ever attended an online conference?</p><p class="translation">Bạn đã từng tham dự hội nghị trực tuyến chưa?</p><p class="note">Ever hỏi về trải nghiệm.</p></article></section>','INTERMEDIATE',4,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Hiện tại hoàn thành (Present Perfect)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t2,'Từ loại trong TOEIC (Parts of Speech)','<p data-n11="summary">Nhận biết danh từ, động từ, tính từ và trạng từ qua vị trí trong câu.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Danh từ gọi tên người/vật/khái niệm; động từ diễn tả hành động hoặc trạng thái; tính từ bổ nghĩa danh từ; trạng từ thường bổ nghĩa động từ, tính từ hoặc trạng từ khác.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Sau mạo từ và tính từ</td><td>a/an/the + (adjective) + noun</td></tr><tr><td>Trước danh từ</td><td>adjective + noun</td></tr><tr><td>Bổ nghĩa động từ</td><td>verb + adverb hoặc adverb + verb</td></tr><tr><td>Sau be/seem/become</td><td>Thường dùng adjective khi mô tả tính chất của chủ ngữ.</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Danh từ thường có hậu tố -tion, -ment, -ness; tính từ -ive, -ful, -able; trạng từ thường -ly. Hậu tố chỉ là gợi ý, phải kiểm tra cấu trúc và nghĩa.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Không phải mọi từ -ly đều là trạng từ: friendly là tính từ. Xác định vị trí trống trước khi dịch các đáp án cùng gốc từ.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="13" data-order="1"><p class="sentence">The new assistant is very efficient.</p><p class="translation">Trợ lý mới làm việc rất hiệu quả.</p><p class="note">Sau is và very cần tính từ efficient.</p></article><article data-example-id="14" data-order="2"><p class="sentence">Please read the instructions carefully.</p><p class="translation">Vui lòng đọc hướng dẫn cẩn thận.</p><p class="note">Carefully bổ nghĩa read.</p></article><article data-example-id="15" data-order="3"><p class="sentence">Customer satisfaction is our priority.</p><p class="translation">Sự hài lòng của khách hàng là ưu tiên của chúng tôi.</p><p class="note">Satisfaction là danh từ làm chủ ngữ.</p></article></section>','BASIC',5,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t2 AND title='Từ loại trong TOEIC (Parts of Speech)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t3,'Câu bị động (Passive Voice)','<p data-n11="summary">Chuyển trọng tâm sang đối tượng nhận hành động bằng be + V3/ed.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Câu bị động nhấn mạnh người hoặc vật chịu tác động. Động từ be mang thì và hòa hợp với chủ ngữ; động từ chính ở dạng quá khứ phân từ V3/ed. Có thể thêm by + tác nhân khi cần.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Hiện tại đơn</td><td>S + am/is/are + V3/ed.</td></tr><tr><td>Quá khứ đơn</td><td>S + was/were + V3/ed.</td></tr><tr><td>Tương lai đơn</td><td>S + will be + V3/ed.</td></tr><tr><td>Động từ khuyết thiếu</td><td>S + can/must/should + be + V3/ed.</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Xác định chủ ngữ tự thực hiện hay nhận hành động. Documents are reviewed: tài liệu được kiểm tra; staff review documents: nhân viên kiểm tra tài liệu.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Không chọn bị động chỉ vì thấy by. Kết hợp nghĩa của chủ ngữ, tính chuyển tác của động từ và dấu hiệu thời gian.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="16" data-order="1"><p class="sentence">All applications are reviewed by the HR team.</p><p class="translation">Tất cả hồ sơ được nhóm nhân sự xem xét.</p><p class="note">Applications nhận hành động; are reviewed.</p></article><article data-example-id="17" data-order="2"><p class="sentence">The contract was signed yesterday.</p><p class="translation">Hợp đồng đã được ký hôm qua.</p><p class="note">Quá khứ đơn bị động: was signed.</p></article><article data-example-id="18" data-order="3"><p class="sentence">Safety helmets must be worn on site.</p><p class="translation">Phải đội mũ bảo hộ tại công trường.</p><p class="note">Must be + V3: worn.</p></article></section>','INTERMEDIATE',6,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t3 AND title='Câu bị động (Passive Voice)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t3,'Câu điều kiện (Conditionals)','<p data-n11="summary">Phân biệt điều kiện có thật và giả định qua cấu trúc của hai mệnh đề.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Câu điều kiện gồm mệnh đề if và mệnh đề kết quả. Loại 0 nói quy luật; loại 1 nói khả năng tương lai; loại 2 nói giả định trái hiện tại hoặc khó xảy ra; loại 3 giả định trái quá khứ.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Loại 0</td><td>If + hiện tại đơn, hiện tại đơn.</td></tr><tr><td>Loại 1</td><td>If + hiện tại đơn, will + V.</td></tr><tr><td>Loại 2</td><td>If + quá khứ đơn, would + V.</td></tr><tr><td>Loại 3</td><td>If + had + V3, would have + V3.</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Unless có nghĩa if not. Khi mệnh đề if đứng đầu câu, thường dùng dấu phẩy trước mệnh đề kết quả. Trong giả định loại 2, were có thể dùng với mọi chủ ngữ.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Trong mẫu điều kiện loại 1 thông thường, không dùng will trong mệnh đề if. Đọc cả hai vế để chọn cấu trúc phù hợp.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="19" data-order="1"><p class="sentence">If you order today, we will ship tomorrow.</p><p class="translation">Nếu bạn đặt hôm nay, chúng tôi sẽ giao ngày mai.</p><p class="note">Khả năng thực tế tương lai: loại 1.</p></article><article data-example-id="20" data-order="2"><p class="sentence">If I were the manager, I would change the schedule.</p><p class="translation">Nếu tôi là quản lý, tôi sẽ đổi lịch.</p><p class="note">Giả định hiện tại: loại 2.</p></article><article data-example-id="21" data-order="3"><p class="sentence">If we had left earlier, we would have arrived on time.</p><p class="translation">Nếu đã rời đi sớm hơn, chúng tôi đã đến đúng giờ.</p><p class="note">Giả định trái quá khứ: loại 3.</p></article></section>','INTERMEDIATE',7,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t3 AND title='Câu điều kiện (Conditionals)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t4,'Mệnh đề quan hệ (Relative Clauses)','<p data-n11="summary">Dùng who, which, that, whose và where để bổ sung thông tin rõ ràng cho danh từ.</p><section data-n11="lecture"><h2>1. Cách dùng</h2><p>Mệnh đề quan hệ bổ nghĩa danh từ đứng trước. Mệnh đề xác định cung cấp thông tin cần thiết; mệnh đề không xác định thêm thông tin và được ngăn bằng dấu phẩy.</p><h2>2. Cấu trúc cần nhớ</h2><table><thead><tr><th>Dạng câu / vị trí</th><th>Cấu trúc</th></tr></thead><tbody><tr><td>Người</td><td>who/that + động từ (chủ ngữ)</td></tr><tr><td>Vật</td><td>which/that + mệnh đề</td></tr><tr><td>Sở hữu</td><td>whose + danh từ</td></tr><tr><td>Nơi chốn</td><td>where + chủ ngữ + động từ</td></tr></tbody></table><h2>3. Dấu hiệu và cách nhận biết</h2><p>Who chỉ người; which chỉ vật; whose thể hiện sở hữu. That dùng trong mệnh đề xác định, không dùng sau dấu phẩy ở mệnh đề không xác định.</p><h2>4. Áp dụng trong TOEIC</h2><blockquote>Xem chỗ trống thiếu chủ ngữ, tân ngữ hay trạng ngữ. The office where we work khác the office which was renovated: câu sau thiếu chủ ngữ.</blockquote><p>Đọc toàn bộ câu, xác định chủ ngữ và mốc thời gian trước khi so sánh các phương án. Hãy chuyển sang phần Ví dụ để xem cách dùng trong bối cảnh công việc.</p></section><section data-n11="examples"><h2>Ví dụ thực tế</h2><article data-example-id="22" data-order="1"><p class="sentence">The consultant who joined today has ten years of experience.</p><p class="translation">Chuyên gia vừa gia nhập hôm nay có mười năm kinh nghiệm.</p><p class="note">Who làm chủ ngữ cho joined.</p></article><article data-example-id="23" data-order="2"><p class="sentence">This is the office where we hold interviews.</p><p class="translation">Đây là văn phòng nơi chúng tôi tổ chức phỏng vấn.</p><p class="note">Where chỉ địa điểm; mệnh đề đã có we làm chủ ngữ.</p></article><article data-example-id="24" data-order="3"><p class="sentence">The employee whose proposal won will receive a bonus.</p><p class="translation">Nhân viên có đề xuất thắng cuộc sẽ nhận thưởng.</p><p class="note">Whose + proposal thể hiện sở hữu.</p></article></section>','ADVANCED',8,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t4 AND title='Mệnh đề quan hệ (Relative Clauses)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Hiện tại hoàn thành tiếp diễn (Present Perfect Continuous)','<p data-n11="summary">Hoạt động kéo dài tới hiện tại hoặc vừa dừng và còn dấu hiệu.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Đặt trọng tâm vào quá trình. Khi nhấn mạnh số việc đã hoàn tất, thường dùng hiện tại hoàn thành đơn.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + have/has been + V-ing</strong></li><li>Phủ định: <strong>S + have/has + not + been V-ing</strong></li><li>Câu hỏi: <strong>Have/Has + S + been + V-ing?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>for + khoảng thời gian, since + mốc bắt đầu, all morning. Đọc cả câu để xác định hoạt động có nối với hiện tại.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">The support team has been answering calls since 8 a.m.</p><p class="translation">Nhóm hỗ trợ đã liên tục trả lời điện thoại từ 8 giờ sáng.</p><p class="note">Since giới thiệu thời điểm bắt đầu.</p></article><article data-example-id="2" data-order="2"><p class="sentence">I have been checking invoices all morning.</p><p class="translation">Tôi đã kiểm tra hóa đơn suốt buổi sáng.</p><p class="note">Trọng tâm là quá trình kiểm tra.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Have you been waiting long?</p><p class="translation">Bạn đã đợi lâu chưa?</p><p class="note">Đưa have lên trước chủ ngữ để hỏi.</p></article></section>','INTERMEDIATE',9,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Hiện tại hoàn thành tiếp diễn (Present Perfect Continuous)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Quá khứ tiếp diễn (Past Continuous)','<p data-n11="summary">Hoạt động đang diễn ra tại một thời điểm trong quá khứ.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Dùng cho hành động làm nền, hành động bị chen ngang hoặc hai hoạt động đang diễn ra song song.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + was/were + V-ing</strong></li><li>Phủ định: <strong>S + was/were + not + V-ing</strong></li><li>Câu hỏi: <strong>Was/Were + S + V-ing?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>At 3 p.m. yesterday, while, when. Hành động đang diễn ra thường dùng tiếp diễn, sự kiện chen ngang thường dùng quá khứ đơn.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">At 3 p.m., we were testing the new checkout system.</p><p class="translation">Lúc 3 giờ chiều, chúng tôi đang thử hệ thống thanh toán mới.</p><p class="note">Were testing cho biết công việc đang diễn ra lúc đó.</p></article><article data-example-id="2" data-order="2"><p class="sentence">I was taking notes when the projector stopped working.</p><p class="translation">Tôi đang ghi chép thì máy chiếu ngừng hoạt động.</p><p class="note">Stopped là sự kiện chen ngang.</p></article><article data-example-id="3" data-order="3"><p class="sentence">While Leo was packing the orders, Ana was printing the labels.</p><p class="translation">Trong khi Leo đóng gói đơn hàng, Ana đang in nhãn.</p><p class="note">Hai hành động làm nền diễn ra song song.</p></article></section>','BASIC',10,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Quá khứ tiếp diễn (Past Continuous)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Quá khứ hoàn thành (Past Perfect)','<p data-n11="summary">Một hành động đã xảy ra trước một mốc hoặc sự kiện khác trong quá khứ.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Xác định hai mốc rồi đặt hành động xảy ra trước vào quá khứ hoàn thành khi cần làm rõ thứ tự. Nếu thứ tự đã rõ, quá khứ đơn cũng có thể phù hợp.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + had + V3</strong></li><li>Phủ định: <strong>S + had + not + V3</strong></li><li>Câu hỏi: <strong>Had + S + V3?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>By the time + mệnh đề quá khứ, before, already. Không dùng chỉ vì câu kể chuyện quá khứ.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">By the time the auditor arrived, we had printed all the receipts.</p><p class="translation">Khi kiểm toán viên đến, chúng tôi đã in hết biên lai.</p><p class="note">Việc in hoàn tất trước lúc kiểm toán viên đến.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The courier had left before I reached the lobby.</p><p class="translation">Nhân viên giao hàng đã đi trước khi tôi xuống sảnh.</p><p class="note">Had left đặt việc rời đi ở mốc sớm hơn.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Had the technician backed up the files before the update?</p><p class="translation">Kỹ thuật viên đã sao lưu tệp trước khi cập nhật chưa?</p><p class="note">Câu hỏi dùng had trước chủ ngữ và backed up ở V3.</p></article></section>','INTERMEDIATE',11,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Quá khứ hoàn thành (Past Perfect)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Quá khứ hoàn thành tiếp diễn (Past Perfect Continuous)','<p data-n11="summary">Hoạt động kéo dài đến hoặc ngay trước một mốc trong quá khứ.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Nhấn mạnh thời lượng hoặc nguyên nhân của trạng thái lúc đó. Dùng quá khứ hoàn thành đơn khi điểm chính là kết quả đã xong.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + had been + V-ing</strong></li><li>Phủ định: <strong>S + had + not + been V-ing</strong></li><li>Câu hỏi: <strong>Had + S + been + V-ing?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>For two hours before, since dawn, by the time + quá khứ. Chọn theo ý nghĩa, vì for cũng xuất hiện ở các thì khác.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">We had been negotiating for weeks before the contract was signed.</p><p class="translation">Chúng tôi đã đàm phán nhiều tuần trước khi hợp đồng được ký.</p><p class="note">Nhấn mạnh thời gian đàm phán trước lúc ký.</p></article><article data-example-id="2" data-order="2"><p class="sentence">Her shoes were wet because she had been working outside.</p><p class="translation">Giày cô ấy ướt vì trước đó cô đã làm việc ngoài trời.</p><p class="note">Hoạt động giải thích tình trạng trong quá khứ.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Had the machine been running all night before it stopped?</p><p class="translation">Máy đã chạy suốt đêm trước khi dừng phải không?</p><p class="note">Had + chủ ngữ + been + V-ing.</p></article></section>','ADVANCED',12,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Quá khứ hoàn thành tiếp diễn (Past Perfect Continuous)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Tương lai đơn (Future Simple)','<p data-n11="summary">Dự đoán, lời hứa, lời đề nghị và quyết định đưa ra lúc nói.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Dùng will cho dự đoán hoặc quyết định tức thời. Với kế hoạch đã định trước, be going to hoặc hiện tại tiếp diễn có thể phù hợp hơn.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + will + V nguyên mẫu</strong></li><li>Phủ định: <strong>S + will + not + V nguyên mẫu</strong></li><li>Câu hỏi: <strong>Will + S + V nguyên mẫu?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>Tomorrow, next week, I think, I promise. Trong mệnh đề thời gian chỉ tương lai sau when, thường dùng hiện tại đơn.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">I will send the confirmation this afternoon.</p><p class="translation">Tôi sẽ gửi xác nhận chiều nay.</p><p class="note">Will biểu thị lời hứa.</p></article><article data-example-id="2" data-order="2"><p class="sentence">I think the store will be busy tomorrow.</p><p class="translation">Tôi nghĩ cửa hàng sẽ đông khách ngày mai.</p><p class="note">Will biểu thị dự đoán.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Will you call me when the parcel arrives?</p><p class="translation">Bạn sẽ gọi cho tôi khi bưu kiện đến chứ?</p><p class="note">Mệnh đề when dùng arrives.</p></article></section>','BASIC',13,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Tương lai đơn (Future Simple)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Tương lai tiếp diễn (Future Continuous)','<p data-n11="summary">Hoạt động đang diễn ra tại một mốc cụ thể trong tương lai.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Đặt người nghe vào một thời điểm trong tương lai và mô tả công việc đang diễn ra lúc đó. Có thể dùng dạng hỏi để hỏi lịch một cách lịch sự.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + will be + V-ing</strong></li><li>Phủ định: <strong>S + will + not + be V-ing</strong></li><li>Câu hỏi: <strong>Will + S + be + V-ing?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>At this time tomorrow, at 10 a.m. next Monday. Nếu nhấn mạnh đã hoàn tất trước một hạn, xem tương lai hoàn thành.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">At this time tomorrow, I will be flying to the trade fair.</p><p class="translation">Giờ này ngày mai, tôi sẽ đang bay đến hội chợ.</p><p class="note">Chuyến bay đang diễn ra tại mốc ngày mai.</p></article><article data-example-id="2" data-order="2"><p class="sentence">We will be interviewing candidates when you arrive.</p><p class="translation">Khi bạn đến, chúng tôi sẽ đang phỏng vấn ứng viên.</p><p class="note">Cuộc phỏng vấn đang diễn ra khi bạn tới.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Will you be using the conference room at noon?</p><p class="translation">Bạn có dùng phòng họp vào buổi trưa không?</p><p class="note">Câu hỏi về lịch sử dụng phòng.</p></article></section>','INTERMEDIATE',14,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Tương lai tiếp diễn (Future Continuous)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Tương lai hoàn thành (Future Perfect)','<p data-n11="summary">Việc sẽ hoàn tất trước hoặc chậm nhất tại một mốc tương lai.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>So sánh một hạn tương lai với kết quả dự kiến. Dạng này thường đi với số lượng hoàn tất hoặc công việc có điểm kết thúc.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + will have + V3</strong></li><li>Phủ định: <strong>S + will + not + have V3</strong></li><li>Câu hỏi: <strong>Will + S + have + V3?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>By Friday, by the end of next month, by the time + hiện tại đơn. By là hạn hoàn thành; until chỉ sự kéo dài tới mốc.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">By Friday, we will have processed all 200 applications.</p><p class="translation">Chậm nhất thứ Sáu, chúng tôi sẽ xử lý xong cả 200 đơn.</p><p class="note">All 200 applications nhấn mạnh kết quả hoàn tất.</p></article><article data-example-id="2" data-order="2"><p class="sentence">The team will have packed every order by the time the truck arrives.</p><p class="translation">Nhóm sẽ đóng gói xong mọi đơn trước lúc xe tải đến.</p><p class="note">Mệnh đề thời gian dùng arrives.</p></article><article data-example-id="3" data-order="3"><p class="sentence">Will you have finished the draft by Tuesday?</p><p class="translation">Bạn sẽ hoàn thành bản nháp chậm nhất thứ Ba chứ?</p><p class="note">Will đứng trước chủ ngữ, sau đó là have + V3.</p></article></section>','ADVANCED',15,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Tương lai hoàn thành (Future Perfect)');
INSERT INTO grammar_lessons(topic_id,title,content_html,level,sort_order,is_published) SELECT @v43_t1,'Tương lai hoàn thành tiếp diễn (Future Perfect Continuous)','<p data-n11="summary">Nhấn mạnh thời lượng của hoạt động tính đến một mốc tương lai.</p><section data-n11="lecture"><h3>Cách dùng</h3><p>Dùng với hoạt động có thể kéo dài như working, running hoặc waiting. Nếu cần nói số lượng đã hoàn thành, dùng tương lai hoàn thành đơn.</p><h3>Công thức</h3><ul><li>Khẳng định: <strong>S + will have been + V-ing</strong></li><li>Phủ định: <strong>S + will + not + have been V-ing</strong></li><li>Câu hỏi: <strong>Will + S + have + been + V-ing?</strong></li></ul><h3>Nhận biết trong TOEIC</h3><p>By next July, for six months by then, by the time + hiện tại đơn. Câu cần cả mốc tương lai lẫn ý kéo dài.</p><p><em>S: chủ ngữ. V3: quá khứ phân từ.</em></p></section><section data-n11="examples"><article data-example-id="1" data-order="1"><p class="sentence">By October, we will have been operating this branch for a year.</p><p class="translation">Đến tháng Mười, chúng tôi sẽ vận hành chi nhánh này được một năm.</p><p class="note">A year đo thời lượng tính đến tháng Mười.</p></article><article data-example-id="2" data-order="2"><p class="sentence">By 5 p.m., the generator will have been running for 12 hours.</p><p class="translation">Đến 5 giờ chiều, máy phát điện sẽ chạy được 12 giờ.</p><p class="note">Trọng tâm là thời gian vận hành.</p></article><article data-example-id="3" data-order="3"><p class="sentence">How long will you have been working here by December?</p><p class="translation">Đến tháng Mười Hai, bạn sẽ làm ở đây được bao lâu?</p><p class="note">How long hỏi thời lượng đến mốc tương lai.</p></article></section>','ADVANCED',16,1 WHERE NOT EXISTS (SELECT 1 FROM grammar_lessons WHERE topic_id=@v43_t1 AND title='Tương lai hoàn thành tiếp diễn (Future Perfect Continuous)');
