INSERT INTO _n11_grammar_import(topic_title,lesson_title,question_text,explanation,difficulty,sort_order,option_a,option_b,option_c,option_d,correct_label) VALUES
('Từ loại', 'Danh từ đếm được và không đếm được', 'The manager requested additional _____ before approving the proposal.', 'Information là danh từ không đếm được và phù hợp sau additional.', 1, 1, 'informations', 'information', 'informing', 'informative', 'B'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'We need _____ chairs for the conference room.', 'Chairs là danh từ số nhiều đếm được nên several là lựa chọn phù hợp.', 1, 2, 'much', 'a little', 'several', 'an', 'C'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'The new _____ is scheduled to arrive on Friday.', 'Equipment là danh từ không đếm được, dùng động từ is ở số ít.', 1, 3, 'equipment', 'equipments', 'equip', 'equipped', 'A'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'Only a _____ of the employees attended the optional workshop.', 'Employees là danh từ đếm được số nhiều nên a few là phù hợp.', 2, 4, 'little', 'few', 'much', 'piece', 'B'),
('Từ loại', 'Danh từ đếm được và không đếm được', 'The technician gave us two useful _____ of advice.', 'Advice không đếm được nên dùng two pieces of advice.', 2, 5, 'units', 'pieces', 'advices', 'many', 'B'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Ms. Park has _____ appointment with the director at 10 a.m.', 'Appointment bắt đầu bằng âm nguyên âm và được nhắc lần đầu.', 1, 1, 'a', 'an', 'the', 'no article', 'B'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Please review _____ contract attached to this email.', 'Attached to this email xác định bản hợp đồng cụ thể.', 1, 2, 'a', 'an', 'the', 'no article', 'C'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'Our branch needs _____ new printer for the reception desk.', 'A new printer là danh từ đếm được số ít chưa xác định.', 1, 3, 'a', 'an', 'the', 'no article', 'A'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', '_____ employee training is important for workplace safety in general.', 'Employee training mang nghĩa khái quát, không cần mạo từ.', 2, 4, 'A', 'An', 'The', 'No article', 'D'),
('Từ loại', 'Mạo từ a, an, the và không mạo từ', 'The conference begins in _____ hour.', 'Hour có h câm nên bắt đầu bằng âm nguyên âm, dùng an.', 2, 5, 'a', 'an', 'the', 'no article', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The marketing team will present _____ plan tomorrow.', 'Trước danh từ plan cần tính từ sở hữu their.', 1, 1, 'they', 'them', 'their', 'theirs', 'C'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'Please forward the confirmation email to _____.', 'Sau giới từ to cần đại từ tân ngữ her.', 1, 2, 'she', 'her', 'hers', 'herself', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'This workstation belongs to Alex; the other one is _____.', 'Mine là đại từ sở hữu đứng độc lập thay cho my workstation.', 2, 3, 'me', 'my', 'mine', 'myself', 'C'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The CEO _____ welcomed the visiting clients.', 'Himself nhấn mạnh chính CEO đã đón tiếp khách hàng.', 2, 4, 'him', 'himself', 'his', 'he', 'B'),
('Từ loại', 'Đại từ nhân xưng, sở hữu và phản thân', 'The software automatically saves _____ settings.', 'Its bổ nghĩa cho settings; it’s là dạng rút gọn của it is.', 2, 5, 'it', 'its', 'itself', 'it’s', 'B'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The analyst completed the monthly report _____.', 'Completed là động từ nên cần trạng từ accurately.', 1, 1, 'accurate', 'accuracy', 'accurately', 'accuracies', 'C'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The company is looking for a _____ project coordinator.', 'Trước danh từ project coordinator cần tính từ reliable.', 1, 2, 'reliability', 'reliably', 'reliable', 'reliance', 'C'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The new ordering system is _____ efficient.', 'Highly là trạng từ bổ nghĩa cho tính từ efficient.', 2, 3, 'high', 'higher', 'height', 'highly', 'D'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The receptionist greeted the visitors _____.', 'Greeted cần trạng từ bổ nghĩa cách thức politely.', 1, 4, 'polite', 'politely', 'politeness', 'polites', 'B'),
('Từ loại', 'Tính từ và trạng từ trong câu TOEIC', 'The annual review was _____ despite the tight deadline.', 'Sau liên động từ was dùng tính từ successful.', 2, 5, 'success', 'successful', 'successfully', 'succeed', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'This delivery service is _____ than the previous one.', 'Than yêu cầu dạng so sánh hơn, fast thành faster.', 1, 1, 'fast', 'faster', 'fastest', 'more faster', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'Of all the applicants, Ms. Green has _____ experience.', 'Of all gợi ý so sánh nhất; extensive dùng the most.', 2, 2, 'extensive', 'more extensive', 'the most extensive', 'as extensive', 'C'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'The updated software is as _____ as the old version.', 'Cấu trúc as + tính từ nguyên dạng + as.', 1, 3, 'stable', 'more stable', 'stablest', 'the most stable', 'A'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'We received _____ complaints this month than last month.', 'Complaints đếm được số nhiều, so sánh lượng dùng fewer.', 2, 4, 'less', 'fewer', 'little', 'the fewest', 'B'),
('Từ loại', 'So sánh hơn, so sánh nhất và so sánh bằng', 'The new warehouse is much _____ from the city center than our old one.', 'Than yêu cầu so sánh hơn; farther phù hợp khoảng cách vật lý.', 2, 5, 'far', 'farthest', 'farther', 'most far', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', '_____ employee must wear an identification badge.', 'Every đi với danh từ đếm được số ít employee.', 1, 1, 'Every', 'Many', 'Few', 'Several', 'A'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'How _____ applications did the HR team receive?', 'Applications là danh từ số nhiều đếm được nên dùng many.', 1, 2, 'much', 'many', 'little', 'every', 'B'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'There is not _____ time left before the meeting.', 'Time là danh từ không đếm được nên dùng much.', 1, 3, 'many', 'a few', 'much', 'several', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'Each of the departments _____ responsible for its own budget.', 'Each of + danh từ số nhiều vẫn lấy each làm trung tâm số ít, dùng is.', 2, 4, 'are', 'be', 'is', 'were', 'C'),
('Từ loại', 'Lượng từ: some, any, much, many, each, every', 'We have _____ questions about the revised contract.', 'Questions là danh từ đếm được số nhiều và some phù hợp câu khẳng định.', 1, 5, 'some', 'much', 'every', 'little', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'All visitors _____ present a valid ID at reception.', 'Sau must là động từ nguyên mẫu present, không có to.', 1, 1, 'must', 'must to', 'musting', 'musted', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'The application _____ be submitted by Friday.', 'Bị động sau modal có dạng must be + V3.', 1, 2, 'must', 'must to', 'musting', 'musters', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'You _____ check the schedule before booking a meeting room.', 'Should + động từ nguyên mẫu để đưa ra lời khuyên.', 1, 3, 'should', 'should to', 'shoulding', 'shoulds', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'Employees _____ enter the laboratory without protective clothing.', 'Cấm vào phòng thí nghiệm nếu không có trang phục bảo hộ: must not.', 2, 4, 'must not', 'do not have to', 'may', 'can', 'A'),
('Từ loại', 'Động từ khuyết thiếu: can, must, should, may', 'If you have already registered, you _____ complete the form again.', 'Do not have to là không cần thiết, không phải cấm.', 2, 5, 'must not', 'do not have to', 'should', 'have to', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'We look forward to _____ from you soon.', 'Look forward to + V-ing, nên chọn hearing.', 1, 1, 'hear', 'hearing', 'heard', 'to hear', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'The board decided _____ the proposal until next week.', 'Decide + to V nên dùng to postpone.', 1, 2, 'postpone', 'postponing', 'to postpone', 'postponed', 'C'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'Employees should avoid _____ personal information online.', 'Avoid + V-ing nên dùng sharing.', 1, 3, 'share', 'to share', 'shared', 'sharing', 'D'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'Ms. Brown suggested _____ the training session online.', 'Suggest + V-ing để đề xuất một hoạt động.', 2, 4, 'hold', 'holding', 'to holding', 'held', 'B'),
('Từ loại', 'Danh động từ (V-ing) và động từ nguyên mẫu (to V)', 'The team agreed _____ the revised schedule.', 'Agree + to V biểu đạt đồng ý làm việc gì.', 2, 5, 'follow', 'following', 'to follow', 'followed', 'C'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The list of approved vendors _____ updated monthly.', 'List là danh từ trung tâm số ít; vendors trong cụm of không quyết định động từ.', 1, 1, 'are', 'be', 'is', 'have', 'C'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'Every employee _____ access to the training portal.', 'Every employee là chủ ngữ số ít nên dùng has.', 1, 2, 'have', 'has', 'are', 'were', 'B'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The reports on the manager’s desk _____ confidential.', 'Reports là danh từ trung tâm số nhiều nên dùng are.', 1, 3, 'is', 'was', 'has', 'are', 'D'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'A number of customers _____ requested refunds.', 'A number of + danh từ số nhiều thường dùng động từ số nhiều have.', 2, 4, 'has', 'have', 'is', 'was', 'B'),
('Cấu trúc câu', 'Hòa hợp chủ ngữ và động từ', 'The number of available rooms _____ decreasing.', 'The number of + danh từ số nhiều lấy number làm trung tâm số ít: is.', 2, 5, 'are', 'is', 'have', 'were', 'B'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The job requires writing reports, managing schedules, and _____ with clients.', 'Chuỗi writing, managing cần V-ing communicating.', 1, 1, 'communicate', 'communicated', 'communicating', 'to communicate', 'C'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The updated procedure is both practical and _____.', 'Both practical and reliable nối hai tính từ.', 1, 2, 'reliability', 'reliably', 'reliable', 'rely', 'C'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'Our goal is to reduce expenses and _____ service quality.', 'To reduce and improve là hai động từ nguyên mẫu song song.', 2, 3, 'improves', 'improved', 'improving', 'improve', 'D'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The training covers customer service, financial reporting, and _____.', 'Danh sách dùng các cụm danh từ/danh động từ, negotiating contracts phù hợp.', 2, 4, 'negotiating contracts', 'to negotiate contracts', 'negotiate contracts', 'negotiated contracts', 'A'),
('Cấu trúc câu', 'Cấu trúc song song (Parallel Structure)', 'The proposal is not only affordable but also _____.', 'Affordable và innovative đều là tính từ trong cấu trúc song song.', 2, 5, 'innovation', 'innovative', 'innovatively', 'innovate', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The committee approved a _____ budget proposal.', 'Trước budget proposal cần tính từ revised.', 1, 1, 'revision', 'revised', 'revise', 'revisingly', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'We need a _____ detailed analysis of the results.', 'Trước tính từ detailed cần trạng từ particularly (đặc biệt chi tiết).', 2, 2, 'particular', 'particularly', 'particularity', 'particulars', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The company launched a new customer _____ program.', 'Cụm danh từ thông dụng là customer satisfaction program.', 2, 3, 'satisfy', 'satisfaction', 'satisfactory', 'satisfying', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The manager shared the _____ sales figures with the board.', 'Trước sales figures cần tính từ monthly.', 1, 4, 'month', 'monthly', 'months', 'monthlyness', 'B'),
('Cấu trúc câu', 'Trật tự từ trong cụm danh từ TOEIC', 'The team submitted a _____ prepared presentation.', 'Bổ nghĩa prepared bằng trạng từ professionally.', 2, 5, 'professional', 'profession', 'professionally', 'professionalism', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The _____ contract must be signed by Friday.', 'Contract nhận hành động chỉnh sửa nên dùng revised.', 1, 1, 'revise', 'revising', 'revised', 'revision', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'Employees _____ in the safety workshop will receive certificates.', 'Employees chủ động tham gia, dùng V-ing participating.', 2, 2, 'participating', 'participated', 'participate', 'participation', 'A'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The presentation was so _____ that everyone stayed until the end.', 'Presentation là tác nhân tạo hứng thú nên dùng interesting.', 1, 3, 'interest', 'interested', 'interesting', 'interests', 'C'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'The customers were _____ by the sudden schedule change.', 'Customers ở trạng thái bất ngờ nên dùng surprised.', 1, 4, 'surprising', 'surprised', 'surprise', 'surprises', 'B'),
('Cấu trúc câu', 'Phân từ hiện tại và phân từ quá khứ', 'Please archive all _____ invoices after payment.', 'Paid invoices là các hóa đơn đã được thanh toán.', 2, 5, 'pay', 'paying', 'paid', 'pays', 'C'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Never _____ the company received so many orders in one day.', 'Never đứng đầu câu yêu cầu đảo ngữ: has the company received.', 3, 1, 'has', 'have', 'had been', 'did has', 'A'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Rarely _____ this printer require maintenance.', 'Hiện tại đơn đảo ngữ với chủ ngữ this printer số ít cần does.', 3, 2, 'do', 'does', 'is', 'has', 'B'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Only after the inspection _____ the workers restart the machines.', 'Only after đặt đầu câu dẫn tới did + chủ ngữ + V nguyên mẫu.', 3, 3, 'was', 'did', 'has', 'are', 'B'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Not until yesterday _____ we receive the revised specifications.', 'Not until + quá khứ dẫn tới đảo ngữ did we receive.', 3, 4, 'do', 'have', 'did', 'are', 'C'),
('Cấu trúc câu', 'Đảo ngữ với trạng từ phủ định và only', 'Hardly had the meeting started _____ the alarm went off.', 'Cặp cấu trúc cố định Hardly had ... when ... .', 3, 5, 'than', 'when', 'that', 'until', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'Could you tell me _____ the meeting starts?', 'When hỏi thời điểm bắt đầu cuộc họp và tạo mệnh đề danh từ.', 1, 1, 'when', 'what', 'that', 'which', 'A'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'The manager confirmed _____ all invoices had been paid.', 'That nối nội dung đã được xác nhận, không cần từ hỏi.', 2, 2, 'which', 'that', 'what', 'who', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'We need to determine _____ the supplier can deliver by Friday.', 'Whether diễn tả cần xác định có thể giao được hay không.', 2, 3, 'whether', 'whose', 'which', 'that time', 'A'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', 'Do you know where _____?', 'Câu hỏi gián tiếp dùng trật tự S + V: where the conference room is.', 2, 4, 'is the conference room', 'the conference room is', 'does the conference room', 'conference room being', 'B'),
('Mệnh đề', 'Mệnh đề danh từ: that, whether, if, what', '_____ the supervisor recommended was accepted by the team.', 'What đóng vai trò đối tượng được đề xuất và làm chủ ngữ cho was accepted.', 3, 5, 'That', 'What', 'Whether', 'If', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', '_____ the roads were flooded, the delivery arrived on time.', 'Although + mệnh đề the roads were flooded.', 1, 1, 'Despite', 'Although', 'Because of', 'During', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'We postponed the inspection _____ the heavy rain.', 'Because of theo sau bởi cụm danh từ the heavy rain.', 1, 2, 'because', 'although', 'because of', 'unless', 'C'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'Please wait here until the technician _____ the system.', 'Mệnh đề thời gian nói về tương lai dùng hiện tại đơn checks.', 2, 3, 'will check', 'checks', 'checking', 'to check', 'B'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', 'You will miss the deadline _____ you submit the report today.', 'Unless = if not, đúng nghĩa nếu không nộp hôm nay.', 2, 4, 'unless', 'although', 'because of', 'despite', 'A'),
('Mệnh đề', 'Mệnh đề trạng ngữ chỉ thời gian, nguyên nhân và nhượng bộ', '_____ the equipment was expensive, the company decided to purchase it.', 'Even though + mệnh đề chỉ nhượng bộ, phù hợp nghĩa đối lập.', 2, 5, 'Because of', 'In spite of', 'Even though', 'Despite', 'C'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The files _____ yesterday are now on the server.', 'Files nhận hành động upload, dùng V3 uploaded.', 2, 1, 'uploading', 'uploaded', 'uploads', 'to upload', 'B'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'Staff members _____ on the night shift receive an allowance.', 'Staff members chủ động làm ca đêm nên dùng working.', 2, 2, 'working', 'worked', 'works', 'to worked', 'A'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The first candidate _____ the interview received the offer.', 'Sau the first candidate dùng to V để chỉ người đầu tiên thực hiện.', 3, 3, 'complete', 'completing', 'to complete', 'completed', 'C'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The proposal _____ by the committee was accepted.', 'Proposal được ủy ban xem xét, dùng reviewed bị động.', 2, 4, 'reviewing', 'reviewed', 'reviews', 'to reviewing', 'B'),
('Mệnh đề', 'Rút gọn mệnh đề quan hệ', 'The people _____ in the lobby are here for the conference.', 'People đang chủ động chờ, dùng waiting.', 2, 5, 'waiting', 'waited', 'waits', 'be waiting', 'A'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'The supervisor _____ us that the meeting would start at nine.', 'Told cần tân ngữ người nhận us; said us là sai.', 1, 1, 'said', 'told', 'spoke', 'talked', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'She asked _____ the shipment had arrived.', 'Whether dẫn câu hỏi gián tiếp có/không.', 2, 2, 'that', 'whether', 'what', 'which', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'He said that he _____ the supplier the following day.', 'Will thường lùi thành would trong lời tường thuật quá khứ.', 2, 3, 'will call', 'would call', 'calls', 'has call', 'B'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'The manager asked the staff _____ quiet during the presentation.', 'Ask someone to V: asked the staff to remain.', 1, 4, 'remain', 'remaining', 'to remain', 'remained', 'C'),
('Mệnh đề', 'Câu tường thuật và thay đổi thì', 'They asked where the new branch _____.', 'Trong câu gián tiếp với asked quá khứ, was located là phù hợp.', 2, 5, 'is located', 'was located', 'located was', 'was locating', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'The monthly review will take place _____ Monday.', 'On đi với tên ngày trong tuần.', 1, 1, 'in', 'on', 'at', 'by', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'Please arrive _____ 8:30 a.m. for registration.', 'At đi với một giờ cụ thể.', 1, 2, 'in', 'on', 'at', 'during', 'C'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'All reimbursement claims must be submitted _____ Friday.', 'By Friday có nghĩa chậm nhất vào thứ Sáu.', 2, 3, 'until', 'since', 'by', 'for', 'C'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'She has worked at this branch _____ 2021.', 'Since theo sau mốc bắt đầu 2021.', 2, 4, 'for', 'since', 'during', 'by', 'B'),
('Giới từ và liên từ', 'Giới từ chỉ thời gian và địa điểm', 'The library will remain open _____ 9 p.m. tonight.', 'Remain open until 9 p.m. là trạng thái kéo dài tới 9 giờ.', 2, 5, 'until', 'by', 'since', 'for', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'Ms. Chen is responsible _____ preparing the quarterly budget.', 'Responsible for + V-ing/danh từ.', 1, 1, 'to', 'of', 'for', 'with', 'C'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'The success of the event depends _____ volunteer support.', 'Depend on là cụm cố định.', 1, 2, 'on', 'at', 'from', 'in', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'All employees must comply _____ the new security regulations.', 'Comply with regulations là cụm cố định.', 2, 3, 'to', 'with', 'for', 'about', 'B'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'The new interns are interested _____ attending the workshop.', 'Interested in + V-ing hoặc danh từ.', 1, 4, 'in', 'to', 'on', 'by', 'A'),
('Giới từ và liên từ', 'Giới từ cố định sau động từ và tính từ', 'We apologize _____ the delay in processing your request.', 'Apologize for + danh từ.', 1, 5, 'on', 'with', 'at', 'for', 'D'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'The seminar was canceled _____ the speaker was ill.', 'Sau chỗ trống là mệnh đề the speaker was ill, nên dùng because.', 1, 1, 'because of', 'because', 'despite', 'during', 'B'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', '_____ the heavy traffic, the delivery truck arrived on time.', 'Despite theo sau cụm danh từ the heavy traffic, diễn tả tương phản.', 2, 2, 'Although', 'Because', 'Despite', 'While', 'C'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'Please keep your phone silent _____ the presentation.', 'During theo sau danh từ the presentation.', 1, 3, 'while', 'during', 'although', 'because', 'B'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', '_____ we were waiting for the manager, we reviewed the agenda.', 'While theo sau mệnh đề we were waiting.', 2, 4, 'During', 'Despite', 'While', 'Because of', 'C'),
('Giới từ và liên từ', 'Phân biệt because/because of, although/despite và during/while', 'The manager approved the purchase _____ the higher price.', 'Despite + noun phrase the higher price diễn tả nhượng bộ.', 2, 5, 'although', 'despite', 'while', 'because', 'B');
